import { expect, test } from "bun:test"
import { payrollRows } from "../src/export/payroll"
import { groupWithVenues } from "./fakes/venues"

test("the payroll export covers every venue of a group, not only the first page", async () => {
  const group = await groupWithVenues(6)
  const rows = await payrollRows(group, "2026-10")
  expect(new Set(rows.map((r) => r.venueId)).size).toBe(6)
})
